// PB2 animatic engine (tools/pb2/animatic): pencil-storyboard animatic drawn on one canvas.
// Beats either carry draw(K, p, t, h) or a scene name from scenes.js plus params (generated by build_animatic.py).
// Contract for tools/atlas_render/render.mjs: window.seek(t), window.DURATION, one canvas.
// A scene file sets window.ANIM = { id, title, duration, beats: [{ t0, t1, label, mode, vo, draw(S, p, t), texts: [...] }] }.
// window.FMT = '9x16' | '4x5' is set by the HTML wrapper.
(function () {
  'use strict';
  const FMT = window.FMT || '9x16';
  const W = 1080, H = FMT === '4x5' ? 1350 : 1920;
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  document.body.style.cssText = 'margin:0;background:#111;display:flex;justify-content:center';
  cv.style.cssText = 'height:96vh;margin-top:2vh';
  document.body.appendChild(cv);
  const c = cv.getContext('2d');
  const STAGE_Y = (H - 1080) / 2;
  const IMAGES = {};   // the beats' params.image (data URIs the build inlined), decoded before the first frame

  // ---------- seeded randomness for the hand-drawn "boil" ----------
  let seedState = 1;
  function reseed(key) {
    let h = 2166136261;
    const s = String(key);
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    seedState = (h >>> 0) || 1;
  }
  function rnd() {
    seedState = (seedState + 0x6d2b79f5) | 0;
    let t = Math.imul(seedState ^ (seedState >>> 15), 1 | seedState);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
  const J = (a) => (rnd() - 0.5) * 2 * a;
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const ease = (p) => (p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2);
  const seg = (p, a, b) => clamp((p - a) / (b - a));
  const lerp = (a, b, k) => a + (b - a) * k;

  // ---------- palette by mode ----------
  const MODES = {
    night: { bg: '#1a2030', ink: '#dde2ec', soft: 'rgba(221,226,236,0.35)', fill: '#252d40' },
    lamp: { bg: '#2a241d', ink: '#f3e8d6', soft: 'rgba(243,232,214,0.35)', fill: '#3a3127' },
    day: { bg: '#efe9dd', ink: '#2b2a28', soft: 'rgba(43,42,40,0.25)', fill: '#e2dacb' },
    card: { bg: '#f4efe4', ink: '#22211f', soft: 'rgba(34,33,31,0.25)', fill: '#e6dfd0' },
  };
  let M = MODES.day;

  // ---------- pencil primitives (stage coordinates, 1080 x 1080) ----------
  function pen(w = 4, col) { c.lineWidth = w; c.strokeStyle = col || M.ink; c.lineCap = 'round'; c.lineJoin = 'round'; }
  function line(x1, y1, x2, y2, j = 2.2) {
    for (let k = 0; k < 2; k++) {
      c.beginPath(); c.moveTo(x1 + J(j), y1 + J(j));
      const mx = (x1 + x2) / 2 + J(j * 1.5), my = (y1 + y2) / 2 + J(j * 1.5);
      c.quadraticCurveTo(mx, my, x2 + J(j), y2 + J(j)); c.stroke();
    }
  }
  function poly(pts, close = false, j = 2) {
    for (let k = 0; k < 2; k++) {
      c.beginPath();
      pts.forEach(([x, y], i) => (i ? c.lineTo(x + J(j), y + J(j)) : c.moveTo(x + J(j), y + J(j))));
      if (close) c.closePath();
      c.stroke();
    }
  }
  function rect(x, y, w, h, j = 2) { poly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], true, j); }
  function ell(cx, cy, rx, ry, j = 2, a0 = 0, a1 = Math.PI * 2) {
    for (let k = 0; k < 2; k++) {
      c.beginPath();
      const n = 36;
      for (let i = 0; i <= n; i++) {
        const a = a0 + (a1 - a0) * (i / n);
        const x = cx + Math.cos(a) * (rx + J(j)), y = cy + Math.sin(a) * (ry + J(j));
        i ? c.lineTo(x, y) : c.moveTo(x, y);
      }
      c.stroke();
    }
  }
  function fillPoly(pts, col) { c.fillStyle = col; c.beginPath(); pts.forEach(([x, y], i) => (i ? c.lineTo(x, y) : c.moveTo(x, y))); c.closePath(); c.fill(); }
  function fillRR(x, y, w, h, r, col) { c.fillStyle = col; c.beginPath(); c.roundRect(x, y, w, h, r); c.fill(); }
  function hatch(x, y, w, h, gap = 18, col) {
    c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip(); pen(2, col || M.soft);
    for (let d = -h; d < w; d += gap) line(x + d, y + h, x + d + h, y, 1.2);
    c.restore();
  }
  function glow(cx, cy, r, col, a = 0.5) {
    const g = c.createRadialGradient(cx, cy, 0, cx, cy, r);
    g.addColorStop(0, col.replace('A', a)); g.addColorStop(1, col.replace('A', 0));
    c.fillStyle = g; c.fillRect(cx - r, cy - r, r * 2, r * 2);
  }
  function hand(str, x, y, size, col, align = 'left', font = '"Segoe Print","Ink Free","Comic Sans MS",cursive') {
    c.fillStyle = col || M.ink; c.font = `${size}px ${font}`; c.textAlign = align; c.textBaseline = 'middle'; c.fillText(str, x, y);
  }

  // ---------- scene components ----------
  const K = {
    room(opts = {}) {
      // floor line and wall corner
      pen(3); line(0, 860, 1080, 860, 3);
      if (opts.window) {
        rect(760, 150, 220, 260, 3); line(870, 150, 870, 410); line(760, 280, 980, 280);
        if (opts.window === 'moon') { ell(925, 205, 22, 22, 1.5); }
        if (opts.window === 'sun') { c.save(); glow(870, 280, 260, 'rgba(255,220,150,A)', 0.55); c.restore(); }
      }
    },
    bed(x = 120, y = 560, w = 700) {
      pen(4); rect(x, y - 260, 40, 340, 3); // headboard
      rect(x + 40, y, w, 70, 3); // mattress
      line(x + 40, y + 70, x + 40, y + 160); line(x + w + 40, y + 70, x + w + 40, y + 160);
    },
    pillow(x = 170, y = 520) { pen(4); ell(x + 90, y, 110, 40, 3); },
    duvet(x = 160, y = 560, w = 680, bump = 0) {
      pen(4);
      poly([[x, y + 10], [x + w * 0.3, y - 30 - bump], [x + w * 0.6, y - 18 - bump * 0.6], [x + w, y + 4]], false, 3);
      line(x, y + 10, x + w, y + 4, 3);
      hatch(x + 30, y - 10, w - 60, 40, 22);
    },
    personSit(x = 330, y = 300, opts = {}) {
      // head
      pen(4); ell(x, y, 62, 72, 2.5);
      // hair
      pen(4); poly([[x - 60, y - 20], [x - 40, y - 70], [x + 10, y - 82], [x + 55, y - 55], [x + 62, y - 15]], false, 3);
      // eyes
      if (opts.eyesClosed) { line(x - 30, y + 5, x - 12, y + 8, 1.2); line(x + 12, y + 8, x + 30, y + 5, 1.2); }
      else { ell(x - 22, y + 2, 5, 6, 0.8); ell(x + 22, y + 2, 5, 6, 0.8); }
      // mouth
      if (opts.talk) ell(x, y + 38, 12, 6 + Math.abs(Math.sin(opts.t * 18)) * 8, 1); else line(x - 14, y + 38, x + 14, y + 38, 1);
      // shoulders / torso
      pen(4); poly([[x - 50, y + 70], [x - 130, y + 120], [x - 150, y + 260]], false, 3);
      poly([[x + 50, y + 70], [x + 130, y + 120], [x + 150, y + 260]], false, 3);
    },
    personLie(x = 300, y = 500, opts = {}) {
      pen(4); ell(x, y, 70, 58, 2.5);
      poly([[x - 66, y - 10], [x - 40, y - 55], [x + 20, y - 62], [x + 66, y - 30]], false, 3);
      if (opts.eyesClosed !== false) { line(x - 30, y + 2, x - 12, y + 6, 1.2); line(x + 12, y + 6, x + 30, y + 2, 1.2); }
      else { ell(x - 22, y, 5, 6, 0.8); ell(x + 22, y, 5, 6, 0.8); }
      if (opts.talk) ell(x, y + 30, 10, 4 + Math.abs(Math.sin(opts.t * 14)) * 6, 1); else line(x - 10, y + 30, x + 10, y + 30, 1);
    },
    notebook(x, y, w, h, written = 0, lines = 6) {
      fillPoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], M === MODES.day || M === MODES.card ? '#fbf8f1' : 'rgba(250,246,236,0.92)');
      const ink = '#2b2a28';
      pen(4, ink); rect(x, y, w, h, 2); line(x + w / 2, y, x + w / 2, y + h, 2);
      pen(2, 'rgba(60,80,120,0.45)');
      for (let i = 1; i <= lines; i++) { const yy = y + (h / (lines + 1)) * i; line(x + 18, yy, x + w / 2 - 18, yy, 1); line(x + w / 2 + 18, yy, x + w - 18, yy, 1); }
      // scribbles revealed by `written`
      pen(3, ink);
      const total = lines * 2, show = Math.floor(total * written);
      for (let i = 0; i < show; i++) {
        const col = i < lines ? 0 : 1, row = i % lines;
        const yy = y + (h / (lines + 1)) * (row + 1) - 8;
        const x0 = x + (col ? w / 2 + 24 : 24), len = (w / 2 - 60) * (0.5 + 0.5 * ((i * 37) % 10) / 10);
        poly(Array.from({ length: 9 }, (_, k) => [x0 + (len * k) / 8, yy + Math.sin(k * 1.7 + i) * 5]), false, 1);
      }
      return { penX: x + 24 + (w / 2 - 60) * ((written * 2) % 1), penY: y + (h / (lines + 1)) * (Math.floor(written * lines) % lines + 1) - 8 };
    },
    penHand(x, y) {
      pen(4); line(x, y, x + 90, y - 120, 2); // pen
      pen(4); ell(x + 110, y - 140, 46, 34, 2.5); // hand blob
      line(x + 70, y - 120, x + 95, y - 165, 2);
    },
    lamp(x = 900, y = 600, on = true) {
      if (on) glow(x, y - 150, 360, 'rgba(255,196,120,A)', 0.55);
      pen(4); poly([[x - 60, y - 210], [x + 60, y - 210], [x + 90, y - 120], [x - 90, y - 120]], true, 2.5);
      line(x, y - 120, x, y, 2); line(x - 50, y, x + 50, y, 2);
    },
    nightstand(x = 830, y = 620) { pen(4); rect(x, y, 200, 240, 3); line(x, y + 110, x + 200, y + 110, 2); },
    clock(x, y, txt, lit = true) {
      fillRR(x, y, 190, 90, 14, '#111');
      pen(3); rect(x, y, 190, 90, 2);
      c.fillStyle = lit ? '#ff6a4d' : '#7a3a30'; c.font = 'bold 58px "Consolas","Courier New",monospace'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillText(txt, x + 95, y + 47);
    },
    phone(x, y, w, h, opts = {}) {
      if (opts.lit) glow(x + w / 2, y + h / 2, Math.max(w, h) * 1.4, 'rgba(170,200,255,A)', 0.35);
      fillRR(x, y, w, h, w * 0.12, '#101318');
      fillRR(x + w * 0.05, y + h * 0.04, w * 0.9, h * 0.92, w * 0.08, opts.lit ? '#dfe8ff' : '#1c2230');
      pen(4); c.beginPath(); c.roundRect(x, y, w, h, w * 0.12); c.stroke();
      if (opts.screen) { c.save(); c.beginPath(); c.roundRect(x + w * 0.05, y + h * 0.04, w * 0.9, h * 0.92, w * 0.08); c.clip(); opts.screen(x + w * 0.05, y + h * 0.04, w * 0.9, h * 0.92); c.restore(); }
    },
    alarmScreen(x, y, w, h, txt) {
      c.fillStyle = '#0d1424'; c.fillRect(x, y, w, h);
      c.fillStyle = '#ffffff'; c.font = `bold ${w * 0.28}px "Segoe UI",Arial`; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillText(txt, x + w / 2, y + h * 0.4);
      c.font = `${w * 0.08}px "Segoe UI",Arial`; c.fillText('Alarm', x + w / 2, y + h * 0.56);
      fillRR(x + w * 0.2, y + h * 0.75, w * 0.6, h * 0.08, h * 0.04, '#ff9f43');
    },
    bookScreen(x, y, w, h, hi = -1) {
      c.fillStyle = '#efe9dd'; c.fillRect(x, y, w, h);
      // cover
      const cw = w * 0.62, ch = cw * 1.42, cx = x + (w - cw) / 2, cy = y + h * 0.05;
      fillRR(cx, cy, cw, ch, 6, '#141820');
      c.fillStyle = '#e9e3d6'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.font = `bold ${cw * 0.1}px Georgia,serif`; c.fillText('LUCID', cx + cw / 2, cy + ch * 0.28); c.fillText('DREAMING', cx + cw / 2, cy + ch * 0.38);
      c.font = `${cw * 0.065}px Georgia,serif`; c.fillText('Night School', cx + cw / 2, cy + ch * 0.5);
      c.save(); c.translate(cx + cw / 2, cy + ch * 0.72); c.rotate(-0.12);
      c.strokeStyle = '#c0392b'; c.lineWidth = 4; c.strokeRect(-cw * 0.36, -ch * 0.05, cw * 0.72, ch * 0.1);
      c.fillStyle = '#c0392b'; c.font = `bold ${cw * 0.08}px "Courier New",monospace`; c.fillText('FIELD NOTES', 0, 2); c.restore();
      // schedule
      const sy = cy + ch + h * 0.03;
      for (let i = 0; i < 7; i++) {
        const yy = sy + i * (h * 0.045);
        if (i === hi) fillRR(x + w * 0.08, yy - h * 0.018, w * 0.84, h * 0.036, 6, '#f4d35e');
        c.fillStyle = '#2b2a28'; c.font = `${w * 0.055}px "Segoe UI",Arial`; c.textAlign = 'left';
        c.fillText(`Night ${i + 1}`, x + w * 0.12, yy);
        c.fillStyle = 'rgba(43,42,40,0.35)'; c.fillRect(x + w * 0.45, yy - 2, w * 0.4, 4);
      }
    },
    // a product on a phone screen, whatever the product: opts.product (its name), opts.screen (what is on the screen:
    // a short text, or a list of lines, `hi` marking one), opts.image (a picture of it). opts.fixture 'book' draws
    // the dry run's book (bookScreen): a test fixture, never a product shot.
    productScreen(x, y, w, h, opts = {}, hi = -1) {
      if (opts.fixture === 'book') return K.bookScreen(x, y, w, h, hi);
      c.fillStyle = '#f4f1ea'; c.fillRect(x, y, w, h);
      const pad = w * 0.09, iw = w - 2 * pad, ih = h * 0.34, iy = y + h * 0.06, faint = 'rgba(43,42,40,0.3)';
      const img = typeof opts.image === 'string' ? IMAGES[opts.image] : null;
      if (img && img.naturalWidth) {
        const k = Math.min(iw / img.naturalWidth, ih / img.naturalHeight), dw = img.naturalWidth * k, dh = img.naturalHeight * k;
        c.drawImage(img, x + pad + (iw - dw) / 2, iy + (ih - dh) / 2, dw, dh);
      } else {   // a picture placeholder: a frame with a hill
        fillRR(x + pad, iy, iw, ih, 12, '#ddd6c8');
        pen(3, faint); poly([[x + pad + iw * 0.15, iy + ih * 0.8], [x + pad + iw * 0.45, iy + ih * 0.35], [x + pad + iw * 0.85, iy + ih * 0.8]], false, 1.5);
      }
      let yy = iy + ih + h * 0.07;
      c.textAlign = 'left'; c.textBaseline = 'middle';
      c.font = `bold ${w * 0.085}px "Segoe UI",Arial`; c.fillStyle = '#2b2a28';
      if (opts.product) wrap(String(opts.product), iw).slice(0, 2).forEach((l) => { c.fillText(l, x + pad, yy); yy += w * 0.1; });
      else { c.fillStyle = faint; c.fillRect(x + pad, yy - 5, iw * 0.6, 10); yy += w * 0.1; }
      yy += h * 0.015;
      c.font = `${w * 0.055}px "Segoe UI",Arial`;
      const fit = (l) => { const ls = wrap(l, iw); return ls.length > 1 ? `${ls[0]}…` : (ls[0] || ''); };
      if (Array.isArray(opts.screen)) {
        opts.screen.slice(0, 7).forEach((l, i) => {
          if (i === hi) fillRR(x + pad * 0.6, yy - h * 0.021, w - pad * 1.2, h * 0.042, 6, '#f4d35e');
          c.fillStyle = '#2b2a28'; c.fillText(fit(String(l)), x + pad, yy); yy += h * 0.052;
        });
      } else if (opts.screen) {
        c.fillStyle = '#2b2a28';
        wrap(String(opts.screen), iw).slice(0, 6).forEach((l) => { c.fillText(l, x + pad, yy); yy += h * 0.05; });
      } else {
        for (let i = 0; i < 4; i++) { c.fillStyle = faint; c.fillRect(x + pad, yy - 2, iw * (0.9 - i * 0.14), 4); yy += h * 0.05; }
      }
    },
    sticky(x, y, s, txt, reveal = 1, rot = -0.04) {
      c.save(); c.translate(x + s / 2, y + s / 2); c.rotate(rot);
      c.fillStyle = 'rgba(0,0,0,0.18)'; c.fillRect(-s / 2 + 8, -s / 2 + 10, s, s);
      c.fillStyle = '#f6d55c'; c.fillRect(-s / 2, -s / 2, s, s);
      const words = txt.split(' '); const n = Math.ceil(words.length * reveal);
      const shown = words.slice(0, n);
      const lines = []; let cur = '';
      c.font = `${s * 0.105}px "Segoe Print","Ink Free",cursive`;
      shown.forEach((w) => { const t = cur ? cur + ' ' + w : w; if (c.measureText(t).width > s * 0.84) { lines.push(cur); cur = w; } else cur = t; });
      if (cur) lines.push(cur);
      c.fillStyle = '#1f2a44'; c.textAlign = 'left'; c.textBaseline = 'middle';
      lines.forEach((l, i) => c.fillText(l, -s * 0.42, -s * 0.3 + i * s * 0.17));
      c.restore();
    },
    selfieFace(cx = 540, cy = 560, opts = {}) {
      if (opts.lit !== false) glow(cx, cy + 260, 640, 'rgba(160,190,255,A)', 0.42);
      pen(5); ell(cx, cy, 250, 300, 3);
      poly([[cx - 250, cy - 60], [cx - 200, cy - 250], [cx - 40, cy - 320], [cx + 140, cy - 290], [cx + 250, cy - 120]], false, 4);
      if (opts.eyesClosed) { line(cx - 140, cy - 20, cx - 70, cy - 8, 1.5); line(cx + 70, cy - 8, cx + 140, cy - 20, 1.5); }
      else { ell(cx - 100, cy - 20, 18, 22, 1); ell(cx + 100, cy - 20, 18, 22, 1); }
      line(cx, cy + 10, cx - 20, cy + 90, 1.5); line(cx - 20, cy + 90, cx + 10, cy + 95, 1.5);
      if (opts.talk) ell(cx, cy + 170, 40, 10 + Math.abs(Math.sin(opts.t * 16)) * 14, 1.5); else line(cx - 45, cy + 170, cx + 45, cy + 170, 1.5);
      if (opts.finger) { pen(5); line(cx + 20, cy + 300, cx + 10, cy + 150, 2); }
    },
    deskTop() { // top-down nightstand surface
      c.fillStyle = M === MODES.day ? '#d9cdb6' : '#3a3026'; c.fillRect(0, 0, 1080, 1080);
      pen(2, M.soft); for (let i = 0; i < 9; i++) line(0, 60 + i * 120 + J(8), 1080, 70 + i * 120 + J(8), 4);
    },
  };

  // ---------- overlays (canvas coordinates) ----------
  function wrap(str, maxW) {
    const words = str.split(' '); const lines = []; let cur = '';
    words.forEach((w) => { const t = cur ? cur + ' ' + w : w; if (c.measureText(t).width > maxW && cur) { lines.push(cur); cur = w; } else cur = t; });
    if (cur) lines.push(cur); return lines;
  }
  function adText(o, k) {
    const a = ease(clamp(k)); if (a <= 0) return;
    c.save(); c.globalAlpha = a;
    const size = o.size || 66;
    if (o.style === 'center' || o.style === 'top') {
      c.font = `800 ${size}px "Segoe UI",Arial,sans-serif`;
      const lines = wrap(o.str, W * 0.84);
      const y0 = o.style === 'center' ? H * 0.47 - ((lines.length - 1) * size * 1.15) / 2 : H * (o.y || 0.17);
      c.textAlign = 'center'; c.textBaseline = 'middle';
      lines.forEach((l, i) => {
        const y = y0 + i * size * 1.15;
        c.lineWidth = size * 0.16; c.strokeStyle = 'rgba(0,0,0,0.75)'; c.strokeText(l, W / 2, y);
        c.fillStyle = '#fff'; c.fillText(l, W / 2, y);
      });
    } else if (o.style === 'box') {
      c.font = `600 ${size}px "Segoe UI",Arial,sans-serif`;
      const lines = wrap(o.str, W * 0.8);
      const y0 = H * 0.16; c.textAlign = 'center'; c.textBaseline = 'middle';
      lines.forEach((l, i) => {
        const y = y0 + i * size * 1.22, tw = c.measureText(l).width;
        fillRR(W / 2 - tw / 2 - 24, y - size * 0.66, tw + 48, size * 1.32, 14, '#fff');
        c.fillStyle = '#111'; c.fillText(l, W / 2, y + 2);
      });
    } else if (o.style === 'chip') {
      c.font = `700 ${size * 0.7}px "Segoe UI",Arial,sans-serif`;
      const tw = c.measureText(o.str).width; const y = o.y ? H * o.y : H * 0.3;
      fillRR(W / 2 - tw / 2 - 28, y - size * 0.5, tw + 56, size, size * 0.5, 'rgba(0,0,0,0.6)');
      c.fillStyle = '#fff'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText(o.str, W / 2, y + 2);
    } else if (o.style === 'cta') {
      c.font = `800 ${size}px "Segoe UI",Arial,sans-serif`;
      const lines = wrap(o.str, W * 0.84); const y0 = o.y ? H * o.y : H * 0.2;
      c.textAlign = 'center'; c.textBaseline = 'middle';
      lines.forEach((l, i) => { c.fillStyle = o.color || '#1b1b1b'; c.fillText(l, W / 2, y0 + i * size * 1.15); });
    }
    c.restore();
  }
  function voBand(str, beatLabel) {
    const bandH = FMT === '4x5' ? 150 : 210;
    const y = H - bandH;
    c.fillStyle = 'rgba(10,10,12,0.78)'; c.fillRect(0, y, W, bandH);
    c.fillStyle = '#f4d35e'; c.font = '700 26px "Consolas","Courier New",monospace'; c.textAlign = 'left'; c.textBaseline = 'top';
    c.fillText(beatLabel, 36, y + 18);
    if (str) {
      c.font = 'italic 36px "Segoe UI",Arial,sans-serif'; c.fillStyle = '#fff';
      const lines = wrap(str, W - 72);
      lines.slice(0, FMT === '4x5' ? 2 : 3).forEach((l, i) => c.fillText(l, 36, y + 58 + i * 44));
    }
  }
  function tag(t, D, id) {
    c.fillStyle = 'rgba(0,0,0,0.55)'; c.fillRect(0, 0, W, 54);
    c.fillStyle = '#f4d35e'; c.fillRect(0, 50, W * (t / D), 4);
    c.font = '700 26px "Consolas","Courier New",monospace'; c.textAlign = 'left'; c.textBaseline = 'middle'; c.fillStyle = '#f4d35e';
    const ts = (s) => `${String(Math.floor(s / 60)).padStart(2, '0')}:${(s % 60).toFixed(1).padStart(4, '0')}`;
    c.fillText(`ANIMATIC · ${id} · ${FMT.replace('x', ':')}`, 30, 27);
    c.textAlign = 'right'; c.fillText(`${ts(t)} / ${ts(D)}`, W - 30, 27);
  }

  // ---------- frame ----------
  function render(t) {
    const A = window.ANIM; const D = A.duration;
    t = clamp(t, 0, D - 1e-6);
    const b = A.beats.find((x) => t >= x.t0 && t < x.t1) || A.beats[A.beats.length - 1];
    const p = (t - b.t0) / (b.t1 - b.t0);
    M = MODES[b.mode || (window.SCENE_MODES || {})[b.scene] || 'day'];
    reseed(`${A.id}-${b.t0}-${Math.floor(t * 8)}`); // boil: new jitter 8x per second
    c.setTransform(1, 0, 0, 1, 0, 0);
    c.fillStyle = M.bg; c.fillRect(0, 0, W, H);
    // stage with a slow push-in
    const zoom = b.zoom ? lerp(b.zoom[0], b.zoom[1], ease(p)) : 1;
    c.save(); c.translate(0, STAGE_Y); c.translate(540, 540); c.scale(zoom, zoom); c.translate(-540, -540);
    const H_ = { pen, line, poly, rect, ell, hatch, glow, hand, fillRR, fillPoly, seg, ease, lerp, J, ctx: c };
    if (b.draw) b.draw(K, p, t, H_);
    else if (b.scene && window.SCENES && window.SCENES[b.scene]) window.SCENES[b.scene](K, p, t, H_, b.params || {});
    else { hand('missing scene: ' + b.scene, 60, 540, 40, '#f55'); }
    c.restore();
    // paper grain vignette
    const g = c.createRadialGradient(W / 2, H / 2, H * 0.3, W / 2, H / 2, H * 0.75);
    g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,0.28)'); c.fillStyle = g; c.fillRect(0, 0, W, H);
    (b.texts || []).forEach((o) => adText(o, (p * (b.t1 - b.t0) - (o.at || 0)) / 0.25));
    voBand(b.vo, `${b.label} · ${b.t0}–${b.t1}s`);
    tag(t, D, A.id);
  }

  window.addEventListener('load', async () => {
    // a product picture is decoded before seek exists, so the renderer (which waits for it) never draws a frame without it
    const pictures = window.ANIM.beats.map((b) => (b.params || {}).image).filter((s) => typeof s === 'string' && s.startsWith('data:image/'));
    await Promise.all([...new Set(pictures)].map((s) => { const i = new Image(); i.src = s; IMAGES[s] = i; return i.decode().catch(() => {}); }));
    window.DURATION = window.ANIM.duration;
    window.seek = (t) => render(t);
    render(0);
    // live preview when opened in a browser
    if (!navigator.webdriver) { const t0 = performance.now(); const loop = () => { render(((performance.now() - t0) / 1000) % window.DURATION); requestAnimationFrame(loop); }; loop(); }
  });
})();
